static int wc_preclass_consistency_check(const char* ip,
		const char* field,
		const char* expected,
		const char* actual)
{
	if (!expected || !actual || strcmp(expected, actual) != 0) {
		fprintf(stderr,
			"[PRECLASS-CONSISTENCY] ip=%s field=%s expected=%s actual=%s\n",
			ip,
			field,
			expected ? expected : "null",
			actual ? actual : "null");
		return 1;
	}
	return 0;
}

